CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,name text NOT NULL,google_sub text UNIQUE NOT NULL,role text NOT NULL DEFAULT 'student' CHECK(role IN ('student','staff','admin','super_admin')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reporter_id uuid NOT NULL REFERENCES users(id),plate_number text,description text NOT NULL,latitude numeric,longitude numeric,incident_datetime timestamptz NOT NULL,evidence_sha256 text NOT NULL,evidence_mime text NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','UNDER_REVIEW','APPROVED','REJECTED','REQUEST_INFO')),ai_confidence numeric,ai_flags jsonb NOT NULL DEFAULT '[]',reviewed_by uuid REFERENCES users(id),reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS penalties(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),report_id uuid NOT NULL REFERENCES reports(id),points integer NOT NULL,amount numeric NOT NULL DEFAULT 0,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id bigserial PRIMARY KEY,actor_id uuid REFERENCES users(id),action text NOT NULL,entity_id uuid,metadata jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS reports_status_idx ON reports(status);CREATE INDEX IF NOT EXISTS reports_created_idx ON reports(created_at);CREATE INDEX IF NOT EXISTS reports_place_idx ON reports(latitude,longitude);
